head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > M > restore]<br/>DataMap 모듈에서 변경된 값(Value)을 한단계 전으로 되돌립니다.",
    "validation" : [        
        "최대 10 개의 변경 사항을 되돌릴 수 있으며, Key 에 관계없이 값(Value)이 변경된 순서대로 되돌립니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }    

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strInput = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataMap ' + strNameSpace + ' id="target1" baseNode="map">';        
    strTarget += '<w2:keyInfo>';
    strTarget += '<w2:key dataType="text" id="key1" name="name1"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key2" name="name2"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key3" name="name3"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key4" name="name4"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key5" name="name5"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key6" name="name6"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key7" name="name7"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key8" name="name8"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key9" name="name9"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key10" name="name10"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key11" name="name11"></w2:key>';
    strTarget += '</w2:keyInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<key1><![CDATA[dm_data1]]></key1>';
    strTarget += '<key2><![CDATA[dm_data2]]></key2>';
    strTarget += '<key3><![CDATA[dm_data3]]></key3>';
    strTarget += '<key4><![CDATA[dm_data4]]></key4>';
    strTarget += '<key5><![CDATA[dm_data5]]></key5>';
    strTarget += '<key6><![CDATA[dm_data6]]></key6>';
    strTarget += '<key7><![CDATA[dm_data7]]></key7>';
    strTarget += '<key8><![CDATA[dm_data8]]></key8>';
    strTarget += '<key9><![CDATA[dm_data9]]></key9>';
    strTarget += '<key10><![CDATA[dm_data10]]></key10>';
    strTarget += '<key11><![CDATA[dm_data11]]></key11>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataMap>';      


    $p.data.create(strTarget);

	// input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');

    scwin.btn_set_onclick();
    scwin.btn_getJSON_onclick();
}



scwin.btn_set_onclick = function (e) {
    for (var i=1; i < 12; i++) {
        target1.set("key"+i, "change"+i);
    }
}



scwin.btn_getJSON_onclick = function (e) {
    let rtn = target1.getJSON();
    let jsonString = JSON.stringify(rtn);

    wf_body_bottom.getObj("scwin").setReturnValue("getJSON : " + jsonString);  
};



scwin.btn_restore_onclick = function (e) {
    for (var i=1; i < 12; i++) {
        target1.restore();
    }

    scwin.btn_getJSON_onclick();
};
